<span class="line">        console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;帧结束时间:&#39;</span><span class="token punctuation">,</span> frame<span class="token punctuation">.</span>end<span class="token punctuation">,</span> <span class="token string">&#39;ms&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
